def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    if not isinstance(n, int):
        raise TypeError("input must be an int")
    if n < 10**30:
        r = int(n ** 0.5)
        while (r + 1) * (r + 1) <= n:
            r += 1
        while r * r > n:
            r -= 1
        return r
    # Binary search: exact for arbitrary-size integers, no floating point.
    lo, hi = 0, max(1, n)
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if mid * mid <= n:
            lo = mid
        else:
            hi = mid
    return lo
